# =========================================================
# AUTENTICAÇÃO DO PAINEL · SUPABASE AUTH
# =========================================================

AUTH_APP_URL = "https://monitoramentog4.streamlit.app/"
AUTH_SESSION_PREFIX = "_monitor_auth_"


def _auth_request(path, method="POST", payload=None, access_token=None, timeout=20):
    """Chama o Supabase Auth usando somente a Publishable key no navegador/servidor Streamlit."""
    url = f"{SUPABASE_URL.rstrip('/')}{path}"
    body = None if payload is None else json.dumps(payload).encode("utf-8")
    headers = {
        "apikey": SUPABASE_PUBLISHABLE_KEY,
        "Accept": "application/json",
        "Content-Type": "application/json",
    }
    if access_token:
        headers["Authorization"] = f"Bearer {access_token}"

    req = Request(url, data=body, headers=headers, method=method)
    try:
        with urlopen(req, timeout=timeout) as response:
            raw = response.read().decode("utf-8", errors="replace")
            if not raw.strip():
                return {}
            return json.loads(raw)
    except HTTPError as exc:
        raw = exc.read().decode("utf-8", errors="replace")
        try:
            parsed = json.loads(raw)
            message = (
                parsed.get("msg")
                or parsed.get("message")
                or parsed.get("error_description")
                or parsed.get("error")
                or raw
            )
        except Exception:
            message = raw or str(exc)
        raise RuntimeError(str(message).strip() or f"HTTP {exc.code}") from exc
    except URLError as exc:
        raise RuntimeError(f"Não foi possível conectar ao serviço de autenticação: {exc.reason}") from exc


def _auth_store_session(data):
    if not isinstance(data, dict):
        raise RuntimeError("Resposta de autenticação inválida.")

    access_token = str(data.get("access_token") or "").strip()
    refresh_token = str(data.get("refresh_token") or "").strip()
    user = data.get("user") if isinstance(data.get("user"), dict) else {}

    if not access_token:
        raise RuntimeError("O Supabase não retornou uma sessão válida.")

    expires_in = int(data.get("expires_in") or 3600)
    st.session_state[f"{AUTH_SESSION_PREFIX}access_token"] = access_token
    st.session_state[f"{AUTH_SESSION_PREFIX}refresh_token"] = refresh_token
    st.session_state[f"{AUTH_SESSION_PREFIX}expires_at"] = time.time() + max(60, expires_in)
    st.session_state[f"{AUTH_SESSION_PREFIX}user"] = user
    st.session_state[f"{AUTH_SESSION_PREFIX}authenticated"] = True


def _auth_clear_session():
    for key in list(st.session_state.keys()):
        if str(key).startswith(AUTH_SESSION_PREFIX):
            st.session_state.pop(key, None)


def _auth_login(email, password):
    return _auth_request(
        "/auth/v1/token?grant_type=password",
        method="POST",
        payload={"email": email.strip(), "password": password},
    )


def _auth_refresh_session():
    refresh_token = str(st.session_state.get(f"{AUTH_SESSION_PREFIX}refresh_token") or "").strip()
    if not refresh_token:
        return False

    try:
        data = _auth_request(
            "/auth/v1/token?grant_type=refresh_token",
            method="POST",
            payload={"refresh_token": refresh_token},
        )
        _auth_store_session(data)
        return True
    except Exception:
        _auth_clear_session()
        return False


def _auth_is_authenticated():
    if not st.session_state.get(f"{AUTH_SESSION_PREFIX}authenticated"):
        return False

    access_token = str(st.session_state.get(f"{AUTH_SESSION_PREFIX}access_token") or "").strip()
    if not access_token:
        _auth_clear_session()
        return False

    expires_at = float(st.session_state.get(f"{AUTH_SESSION_PREFIX}expires_at") or 0)
    if expires_at and time.time() >= (expires_at - 90):
        return _auth_refresh_session()

    return True


def _auth_logout():
    token = str(st.session_state.get(f"{AUTH_SESSION_PREFIX}access_token") or "").strip()
    if token:
        try:
            _auth_request("/auth/v1/logout", method="POST", payload={}, access_token=token, timeout=10)
        except Exception:
            pass
    _auth_clear_session()


def _auth_recover(email):
    # O link de recuperação é montado no template de e-mail com TokenHash.
    return _auth_request(
        "/auth/v1/recover",
        method="POST",
        payload={"email": email.strip()},
    )


def _auth_verify_token_hash(token_hash, flow_type):
    if flow_type not in {"recovery", "invite"}:
        raise RuntimeError("Tipo de link de autenticação inválido.")
    return _auth_request(
        "/auth/v1/verify",
        method="POST",
        payload={"token_hash": token_hash, "type": flow_type},
    )


def _auth_update_password(access_token, new_password):
    return _auth_request(
        "/auth/v1/user",
        method="PUT",
        payload={"password": new_password},
        access_token=access_token,
    )


def _auth_error_pt(message):
    msg = str(message or "").strip()
    low = msg.lower()

    if "invalid login credentials" in low:
        return "E-mail ou senha inválidos."
    if "email not confirmed" in low:
        return "O e-mail ainda não foi confirmado."
    if "user not found" in low:
        return "E-mail ou senha inválidos."
    if "password should be at least" in low or "weak password" in low:
        return "A senha não atende aos requisitos mínimos de segurança."
    if "token has expired" in low or "otp_expired" in low:
        return "Este link expirou ou já foi utilizado. Solicite uma nova recuperação de senha."
    if "rate limit" in low or "security purposes" in low:
        return "Muitas tentativas em pouco tempo. Aguarde um momento e tente novamente."
    return msg or "Não foi possível concluir a autenticação."


